document.addEventListener('htmx:afterSwap', function (e) { if (e.detail.target.id === 'post-list') { var form = document.querySelector('form[hx-post*="/post"]'); if (form) { var ta = form.querySelector('textarea[name="content"]'); if (ta) { ta.value = '' } var previewBtn = form.querySelector('button[data-state]'); if (previewBtn && previewBtn.getAttribute('data-state') === 'on') { previewBtn.click() } } } });
